                Vector256<byte> hi = Avx2.And(Avx2.ShiftRightLogical(vec.AsInt16(), 4).AsByte(), mask0F256);
                Vector256<byte> reversedLo = Avx2.Shuffle(highNibbleLut: highLut256, lo);
                Vector256<byte> reversedHi = Avx2.Shuffle(lowLut256, hi);
                Vector256<byte> result = Avx2.Or(reversedLo, reversedHi);
                Unsafe.WriteUnaligned(ref Unsafe.Add(ref src, offset), result);
                offset += 32;
            }
        }

        // Process remaining 16-byte chunks with SSSE3
        nuint vectorEnd128 = length - 15;
        while (offset <= vectorEnd128)
        {
            Vector128<byte> vec = Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref src, offset));
            Vector128<byte> lo = Sse2.And(vec, mask0F);
            Vector128<byte> hi = Sse2.And(Sse2.ShiftRightLogical(vec.AsInt16(), 4).AsByte(), mask0F);
            Vector128<byte> reversedLo = Ssse3.Shuffle(highNibbleLut, lo);
            Vector128<byte> reversedHi = Ssse3.Shuffle(lowNibbleLut, hi);
            Vector128<byte> result = Sse2.Or(reversedLo, reversedHi);
            Unsafe.WriteUnaligned(ref Unsafe.Add(ref src, offset), result);
            offset += 16;
        }

        // Scalar tail
        for (; offset < length; offset++)
        {
            Unsafe.Add(ref src, offset) = Unsafe.Add(ref Unsafe.AsRef(in lut[0]), Unsafe.Add(ref src, offset));
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseWithAdvSimd(Span<byte> data)
    {
        // ARM NEON: use RBIT (reverse bits in each byte via vector)
        ref byte src = ref MemoryMarshal.GetReference(data);
        nuint length = (nuint)data.Length;
        nuint offset = 0;

        Vector128<byte> lowNibbleLut = Vector128.Create(
            (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
            0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);
        Vector128<byte> highNibbleLut = Vector128.Create(
            (byte)0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
            0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0);
        Vector128<byte> mask0F = Vector128.Create((byte)0x0F);

        nuint vectorEnd = length - 15;
        while (offset <= vectorEnd)
        {
            Vector128<byte> vec = Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref src, offset));
            Vector128<byte> lo = AdvSimd.And(vec, mask0F);
            Vector128<byte> hi = AdvSimd.And(AdvSimd.ShiftRightLogical(vec, 4), mask0F);
            Vector128<byte> reversedLo = AdvSimd.Arm64.VectorTableLookup(highNibbleLut, lo);
            Vector128<byte> reversedHi = AdvSimd.Arm64.VectorTableLookup(lowNibbleLut, hi);
            Vector128<byte> result = AdvSimd.Or(reversedLo, reversedHi);
            Unsafe.WriteUnaligned(ref Unsafe.Add(ref src, offset), result);
            offset += 16;
        }

        // Scalar tail
        ReadOnlySpan<byte> lut = LookupTable;
        for (; offset < length; offset++)
        {
            Unsafe.Add(ref src, offset) = Unsafe.Add(ref Unsafe.AsRef(in lut[0]), Unsafe.Add(ref src, offset));
        }
    }

    private static void ReverseWithLookup(Span<byte> data)
    {
        ReadOnlySpan<byte> lut = LookupTable;
        ref byte src = ref MemoryMarshal.GetReference(data);
        ref byte lutRef = ref Unsafe.AsRef(in lut[0]);
        nuint length = (nuint)data.Length;

